"""Apply focused integration edits, preserving existing file line endings."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
def edit(name, before, after):
    p=ROOT/name; raw=p.read_bytes(); text=raw.decode('utf-8'); newline='\r\n' if b'\r\n' in raw else '\n'
    text=text.replace('\r\n','\n')
    if before not in text: raise RuntimeError('Missing anchor: '+name+' '+before[:70])
    text=text.replace(before,after,1);p.write_bytes(text.replace('\n',newline).encode('utf-8'))

